vec2 rotate(vec2 v, float angle) {

    float s = sin(angle);
    float c = cos(angle);
    return vec2(c*v.x - s*v.y, s*v.x + c*v.y);
}

void mainImage( out vec4 fragColor, in vec2 fragCoord )
{

    // Normalize pixel coordinates (from 0 to 1)
    vec2 uv = fragCoord.xy / iResolution.xy;

    // Center the coordinates and correct for aspect ratio
    uv = uv * 2.0 - 1.0;
    uv.x *= iResolution.x / iResolution.y;

    // Apply a time-based rotation to swirl the space
    uv = rotate(uv, iTime * 0.3);

    // Compute polar coordinates
    float r = length(uv);
    float angle = atan(uv.y, uv.x);

    // Create a layered wave pattern
    float waves = sin(12.0 * r - iTime * 2.0 + 5.0 * sin(3.0 * angle));

    // Map the wave output to a dynamic color palette
    vec3 col = vec3(

        0.5 + 0.5 * sin(iTime + waves + 0.0),
        0.5 + 0.5 * sin(iTime + waves + 2.0),
        0.5 + 0.5 * sin(iTime + waves + 4.0)
    );

    // Apply a vignette effect to soften the edges
    float vignette = smoothstep(0.8, 0.2, r);
    col *= vignette;
    fragColor = vec4(col, 1.0);

}
